-- GENERATED by scripts/generate_seed.py -- do not edit by hand.
-- Re-run: python3 scripts/generate_seed.py
begin;

  on conflict (domain) do nothing;
  on conflict (email) do nothing;

  on conflict (name) do nothing;
select ay.id, t.q::quarter, t.o from academic_years ay,
  (values ('autumn',1),('winter',2),('spring',3)) as t(q,o)
  on conflict (academic_year_id, quarter) do nothing;

  on conflict (code) do nothing;

  on conflict (day_pattern, start_time, end_time) do nothing;

  on conflict (subject, number) do nothing;

-- Roster = CSS faculty directory + anyone who appears in the imported
-- time schedules but is not listed on the directory page.
  on conflict (full_name) do nothing;

-- Imported from past-course-schedules/*.pdf (AUT2025, WIN2026, SPR2026).
create temp table _hist (
  instructor_name text, instructor_raw text, course_num int, course_code text,
  academic_year text, quarter text, section_letter text, sln text,
  days smallint[], start_time time, end_time time, room_label text,
  enrollment int, enrollment_cap int, modality text) on commit drop;

  course_code_raw, academic_year, quarter, section_letter, sln, days,
  start_time, end_time, room_label, enrollment, enrollment_cap, modality)
select i.id, h.instructor_raw, c.id, h.course_code, h.academic_year,
       h.quarter::quarter, h.section_letter, h.sln, h.days, h.start_time,
       h.end_time, h.room_label, h.enrollment, h.enrollment_cap, h.modality::modality
from _hist h
left join instructors i on i.full_name = h.instructor_name
left join courses c on c.subject = 'CSS' and c.number = h.course_num
on conflict (academic_year, quarter, sln, section_letter) do nothing;

-- Anyone who has taught a course is presumed qualified to teach it again.
select distinct th.instructor_id, th.course_id, 'history'::qualification_source
from teaching_history th
where th.instructor_id is not null and th.course_id is not null
on conflict (instructor_id, course_id) do nothing;

commit;
